	@Test
	void timeoutSignalReturnsWithoutClosingBlockingDelegate() throws Exception {
		CountDownLatch closeEntered = new CountDownLatch(1);
		CountDownLatch releaseClose = new CountDownLatch(1);
		CountDownLatch cancellationRequested = new CountDownLatch(1);
		CooperativeBlockingIteration delegate = CooperativeBlockingIteration.closeOnly(closeEntered, releaseClose,
				cancellationRequested, true);
		TestTimeLimitIteration iteration = new TestTimeLimitIteration(delegate, LONG_TIME_LIMIT_MILLIS);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		Future<?> signal = executor.submit(iteration::interrupt);

		try {
			signal.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
			assertEquals(0L, cancellationRequested.getCount(),
					"the timeout wrapper must delegate a cooperative cancellation request");
			assertEquals(1L, closeEntered.getCount(),
					"an accepted cooperative request must not close the delegate on the timer thread");
		} finally {
			releaseClose.countDown();
			if (!signal.isDone()) {
				signal.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
			}
			iteration.close();
			executor.shutdownNow();
			executor.awaitTermination(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
		}
	}

	@Test
	void nonCooperativeTimeoutRetainsSynchronousClose() throws Exception {
		CountDownLatch closeEntered = new CountDownLatch(1);
		CountDownLatch releaseClose = new CountDownLatch(1);
		BlockingIteration delegate = BlockingIteration.closeOnly(closeEntered, releaseClose);
		TestTimeLimitIteration iteration = new TestTimeLimitIteration(delegate, LONG_TIME_LIMIT_MILLIS);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		Future<?> signal = executor.submit(iteration::interrupt);

		try {
			assertTrue(closeEntered.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS),
					"a non-cooperative delegate must be closed synchronously");
			assertFalse(signal.isDone(), "the timeout signal must not return before synchronous close completes");
		} finally {
			releaseClose.countDown();
			signal.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
			iteration.close();
			executor.shutdownNow();
			executor.awaitTermination(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
		}
	}

	@Test
	void acceptedCancellationDuringNextDoesNotLeakReturnedValue() throws Exception {
		CountDownLatch nextEntered = new CountDownLatch(1);
		CountDownLatch releaseNext = new CountDownLatch(1);
		BlockingNextIteration delegate = new BlockingNextIteration(nextEntered, releaseNext);
		TestTimeLimitIteration iteration = new TestTimeLimitIteration(delegate, LONG_TIME_LIMIT_MILLIS);
		ExecutorService executor = Executors.newFixedThreadPool(2);
		Future<String> worker = executor.submit(iteration::next);
		Future<?> signal = null;

		try {
			assertTrue(nextEntered.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS),
					"the delegate next call must be in flight before cancellation");
			signal = executor.submit(iteration::interrupt);
			signal.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
			releaseNext.countDown();

			ExecutionException timeout = assertThrows(ExecutionException.class,
					() -> worker.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS));
			assertInstanceOf(TestTimeoutException.class, timeout.getCause(),
					"an accepted timeout must win over a value returned by the in-flight next call");
		} finally {
			releaseNext.countDown();
			if (signal != null && !signal.isDone()) {
				signal.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
			}
			if (!worker.isDone()) {
				worker.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
			}
			iteration.close();
			executor.shutdownNow();
			executor.awaitTermination(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
		}
	}

	@Test
	void wrapperDelegationReportsAcceptedAndDeclinedRequests() {
		CountDownLatch acceptedRequest = new CountDownLatch(1);
		TestTimeLimitIteration accepting = new TestTimeLimitIteration(
				CooperativeBlockingIteration.closeOnly(new CountDownLatch(0), new CountDownLatch(0), acceptedRequest,
						true),
				LONG_TIME_LIMIT_MILLIS);
		try {
			CooperativeCancellation cancellation = assertInstanceOf(CooperativeCancellation.class, accepting);
			assertTrue(cancellation.requestCancellation(), "the wrapper must report an accepted downstream request");
			assertEquals(0L, acceptedRequest.getCount());
		} finally {
			accepting.close();
		}

		CountDownLatch declinedRequest = new CountDownLatch(1);
		TestTimeLimitIteration declining = new TestTimeLimitIteration(
				CooperativeBlockingIteration.closeOnly(new CountDownLatch(0), new CountDownLatch(0), declinedRequest,
						false),
				LONG_TIME_LIMIT_MILLIS);
		try {
			CooperativeCancellation cancellation = assertInstanceOf(CooperativeCancellation.class, declining);
			assertFalse(cancellation.requestCancellation(), "the wrapper must report a declined downstream request");
			assertEquals(0L, declinedRequest.getCount());
		} finally {
			declining.close();
		}

		TestTimeLimitIteration unsupported = new TestTimeLimitIteration(new EmptyIteration<>(),
				LONG_TIME_LIMIT_MILLIS);
		try {
			CooperativeCancellation cancellation = assertInstanceOf(CooperativeCancellation.class, unsupported);
			assertFalse(cancellation.requestCancellation(),
					"a wrapper with no cooperative downstream target must decline the request");
		} finally {
			unsupported.close();
		}

		CountDownLatch closedRequest = new CountDownLatch(1);
		TestTimeLimitIteration closed = new TestTimeLimitIteration(
				CooperativeBlockingIteration.closeOnly(new CountDownLatch(0), new CountDownLatch(0), closedRequest,
						true),
				LONG_TIME_LIMIT_MILLIS);
		closed.close();
		CooperativeCancellation closedCancellation = assertInstanceOf(CooperativeCancellation.class, closed);
		assertFalse(closedCancellation.requestCancellation(), "a closed wrapper must decline cancellation");
		assertEquals(1L, closedRequest.getCount(), "a closed wrapper must not call its downstream target");

		RuntimeException failure = new RuntimeException("cooperative cancellation failed");
		TestTimeLimitIteration failing = new TestTimeLimitIteration(new FailingCancellationIteration(failure),
				LONG_TIME_LIMIT_MILLIS);
		try {
			CooperativeCancellation cancellation = assertInstanceOf(CooperativeCancellation.class, failing);
			assertSame(failure, assertThrows(RuntimeException.class, cancellation::requestCancellation),
					"wrapper delegation must not swallow downstream runtime failures");
		} finally {
			failing.close();
		}
	}

	@Test
	void globalTimerRemainsReusableWhileEarlierEvaluationUnwinds() throws Exception {
		CountDownLatch hasNextEntered = new CountDownLatch(1);
		CountDownLatch releaseHasNext = new CountDownLatch(1);
		CountDownLatch closeEntered = new CountDownLatch(1);
		CountDownLatch releaseClose = new CountDownLatch(1);
		CountDownLatch timeoutSignalEntered = new CountDownLatch(1);
		CountDownLatch cancellationRequested = new CountDownLatch(1);
		CooperativeBlockingIteration blockedDelegate = new CooperativeBlockingIteration(hasNextEntered, releaseHasNext,
				closeEntered, releaseClose, cancellationRequested, true);
		ObservedTimeLimitIteration blocked = new ObservedTimeLimitIteration(blockedDelegate,
				EARLIER_TIME_LIMIT_MILLIS, timeoutSignalEntered);
		ExecutorService executor = Executors.newFixedThreadPool(2);
		AtomicReference<Throwable> workerFailure = new AtomicReference<>();
		Future<?> blockedWorker = executor.submit(() -> {
			try {
				blocked.hasNext();
			} catch (TestTimeoutException expected) {
				// The evaluation worker, not the global timer, owns timeout unwinding.
			} catch (Throwable failure) {
				workerFailure.set(failure);
			}
		});

		SignallingTimeLimitIteration later = null;
		try {
			assertTrue(hasNextEntered.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS),
					"the first evaluation must be in flight before scheduling the later timeout");
			assertTrue(timeoutSignalEntered.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS),
					"the first timeout signal must run before scheduling the later timeout");
			later = new SignallingTimeLimitIteration(new EmptyIteration<>(), SHORT_TIME_LIMIT_MILLIS);
			SignallingTimeLimitIteration scheduledLater = later;
			Future<Boolean> laterSignal = executor.submit(
					() -> scheduledLater.interruptCalled.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS));

			assertTrue(laterSignal.get(FUTURE_TIMEOUT_SECONDS + 1L, TimeUnit.SECONDS),
					"a blocked evaluation must not monopolize the process-wide timeout timer");
			assertEquals(0L, cancellationRequested.getCount(),
					"the earlier timeout must be accepted by the cooperative delegate");
			assertEquals(1L, closeEntered.getCount(),
					"the timer must only signal; delegate close belongs to the evaluation worker");
		} finally {
			releaseClose.countDown();
			releaseHasNext.countDown();
			blockedWorker.get(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
			blocked.close();
			if (later != null) {
				later.close();
			}
			executor.shutdownNow();
			executor.awaitTermination(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
		}

		assertFalse(workerFailure.get() != null, () -> "unexpected evaluation worker failure: " + workerFailure.get());
	}

	@Test
	void timerSurvivesCooperativeCancellationRequestFailure() throws Exception {
		CountDownLatch requestEntered = new CountDownLatch(1);
		CountDownLatch releaseRequest = new CountDownLatch(1);
		RuntimeException failure = new RuntimeException("cooperative cancellation failed");
		TestTimeLimitIteration failing = new TestTimeLimitIteration(
				new FailingCancellationIteration(failure, requestEntered, releaseRequest), SHORT_TIME_LIMIT_MILLIS);
		ExecutorService executor = Executors.newSingleThreadExecutor();
		SignallingTimeLimitIteration later = null;

		try {
			assertTrue(requestEntered.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS),
					"the first timeout must reach the failing cooperative request");
			later = new SignallingTimeLimitIteration(new EmptyIteration<>(), SHORT_TIME_LIMIT_MILLIS);
			SignallingTimeLimitIteration scheduledLater = later;
			Future<Boolean> laterSignal = executor.submit(
					() -> scheduledLater.interruptCalled.await(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS));
			releaseRequest.countDown();

			assertTrue(laterSignal.get(FUTURE_TIMEOUT_SECONDS + 1L, TimeUnit.SECONDS),
					"a cooperative-request failure must not terminate the process-wide timeout timer");
		} finally {
			releaseRequest.countDown();
			failing.close();
			if (later != null) {
				later.close();
			}
			executor.shutdownNow();
			executor.awaitTermination(FUTURE_TIMEOUT_SECONDS, TimeUnit.SECONDS);
		}
	}

