	private static class BlockingIteration implements CloseableIteration<String> {

		private final CountDownLatch hasNextEntered;
		private final CountDownLatch releaseHasNext;
		private final CountDownLatch closeEntered;
		private final CountDownLatch releaseClose;

		private BlockingIteration(CountDownLatch hasNextEntered, CountDownLatch releaseHasNext,
				CountDownLatch closeEntered, CountDownLatch releaseClose) {
			this.hasNextEntered = hasNextEntered;
			this.releaseHasNext = releaseHasNext;
			this.closeEntered = closeEntered;
			this.releaseClose = releaseClose;
		}

		private static BlockingIteration closeOnly(CountDownLatch closeEntered, CountDownLatch releaseClose) {
			CountDownLatch unusedEntered = new CountDownLatch(0);
			CountDownLatch unusedRelease = new CountDownLatch(0);
			return new BlockingIteration(unusedEntered, unusedRelease, closeEntered, releaseClose);
		}

		@Override
		public boolean hasNext() {
			hasNextEntered.countDown();
			await(releaseHasNext, "blocked hasNext release");
			return true;
		}

		@Override
		public String next() {
			throw new NoSuchElementException();
		}

		@Override
		public void remove() {
			throw new UnsupportedOperationException();
		}

		@Override
		public void close() {
			closeEntered.countDown();
			await(releaseClose, "blocked close release");
		}
	}

	private static final class CooperativeBlockingIteration extends BlockingIteration
			implements CooperativeCancellation {

		private final CountDownLatch cancellationRequested;
		private final boolean acceptsCancellation;

		private CooperativeBlockingIteration(CountDownLatch hasNextEntered, CountDownLatch releaseHasNext,
				CountDownLatch closeEntered, CountDownLatch releaseClose, CountDownLatch cancellationRequested,
				boolean acceptsCancellation) {
			super(hasNextEntered, releaseHasNext, closeEntered, releaseClose);
			this.cancellationRequested = cancellationRequested;
			this.acceptsCancellation = acceptsCancellation;
		}

		private static CooperativeBlockingIteration closeOnly(CountDownLatch closeEntered,
				CountDownLatch releaseClose, CountDownLatch cancellationRequested, boolean acceptsCancellation) {
			return new CooperativeBlockingIteration(new CountDownLatch(0), new CountDownLatch(0), closeEntered,
					releaseClose, cancellationRequested, acceptsCancellation);
		}

		@Override
		public boolean requestCancellation() {
			cancellationRequested.countDown();
			return acceptsCancellation;
		}
	}

